namespace Target;

public static class FileStore
{
    public static string Resolve(string root, string relativePath)
    {
        if (Path.IsPathRooted(relativePath))
        {
            throw new ArgumentException("The path must be relative.", nameof(relativePath));
        }

        var fullRoot = Path.GetFullPath(root);
        var fullPath = Path.GetFullPath(Path.Combine(fullRoot, relativePath));
        var pathFromRoot = Path.GetRelativePath(fullRoot, fullPath);

        if (Path.IsPathRooted(pathFromRoot) ||
            pathFromRoot == ".." ||
            pathFromRoot.StartsWith($"..{Path.DirectorySeparatorChar}", StringComparison.Ordinal) ||
            pathFromRoot.StartsWith($"..{Path.AltDirectorySeparatorChar}", StringComparison.Ordinal))
        {
            throw new ArgumentException("The path must remain within the storage root.", nameof(relativePath));
        }

        return fullPath;
    }
}
